const { EOL } = require('node:os')
const cds = require('../cds')
const YAML = require('yaml')
const { copy, read, write, exists, path: {resolve, join} } = cds.utils
const { readYAML, writeYAML, readJSON } = require('../util/fs')
const { detectIndent } = require('./indent')

function _mergeObject(target, source) {
  const _isObject = item => item && typeof item === 'object' && !Array.isArray(item)
  const unique = array => [...new Set(array.map(JSON.stringify))].map(JSON.parse)
  if (_isObject(target) && _isObject(source)) {
      for (const key in source) {
          if (_isObject(source[key])) {
              if (!target[key]) Object.assign(target, { [key]: source[key] })
              else _mergeObject(target[key], source[key])
          } else if (Array.isArray(source[key]) && Array.isArray(target[key])) {
              target[key] = unique([...source[key], ...target[key]])
          } else {
              Object.assign(target, { [key]: target[key] || source[key] })
          }
      }
  } else if (Array.isArray(target) && Array.isArray(source)) {
      target = unique([...source, ...target])
  }
  return target ?? source
}

module.exports.sort = async function(path, key) {
  const json = await read(path)
  json[key] = Object.fromEntries(
      Object.entries(json[key] ?? {}).sort(([a],[b]) => a>b ? 1 : -1)
  )
  await write(path, json, { spaces: 2 });
}

/**
 * @param {string} into - file path to merge into
 * @param {string | string[]} from - either path to file (string) or lines from source gitignore (string[])
 * @returns {Promise<string[]>} the lines of the updated .gitignore
 */
module.exports.mergeGitignore = async function(into, from) {
    const source = typeof from === 'string' ? (await read(from)).split(EOL) : from

    if (typeof into === 'string' && !exists(into)) {
      return write(into, source.join(EOL))
    }

    const target = (await read(into)).split(EOL)
    const enhanced = target.concat(source.filter(line => !target.includes(line)))
    await write(into, enhanced.join(EOL))
    return enhanced
}

/**
 * @param {string | JSON} into - file path or JSON to merge into
 * @param {string | JSON} from - file path or JSON to merge from
 * @param {import('./projectReader').readProject} [project] - project descriptor used for Mustache replacements
 * @param {MergingSemantics} [semantics] - merging algorithm semantics
 * @returns {Promise<JSON>} - merged JSON
 */
async function _mergeJSON(into, from, project, semantics) {
    const source = typeof from === 'string' ? await readJSON(from, project) : from

    let result
    if (typeof into === 'string' && !exists(into)) {
        result = source
    } else if (semantics) {
        const target = await read(into)
        const targetYAML = YAML.parseDocument(YAML.stringify(target))
        const sourceYAML = YAML.parseDocument(YAML.stringify(source))
        const resultYAML = await _mergeYAML(targetYAML, sourceYAML, project, semantics)
        result = YAML.parse(YAML.stringify(resultYAML))
    } else {
        const target = typeof into === 'string' ? await read(into, 'json') : into
        result = _mergeObject(target, source)
    }
    // we need to stringify result on site to be able to apply the appropriate indentation.
    // cds-utils.write is currently hardcoded to use spaces for indentation.
    if (typeof into === 'string') {
        const indent = exists(into) && detectIndent((await read(into, 'utf-8')).split(EOL)) || '  '
        await write(into, JSON.stringify(result, null, indent) + EOL)
    }
    return result
}

/**
 * @param {string | YAML.Document | object} into - file path or YAML to merge into
 * @param {string | YAML.Document | object} from - file path or YAML to merge from
 * @param {Object} [project] - project descriptor used for Mustache replacements
 * @param {MergingSemantics} [semantics] - merging algorithm semantics
 * @returns {Promise<YAML.Document>} - merged YAML
 * @throws {Error} Throws an error if empty target YAML is passed in
 */
async function _mergeYAML(into, from, project, semantics = {}) {
    const target = typeof into === 'string'      ? await readYAML(into) :
                   into instanceof YAML.Document ? into :
                   new YAML.Document(into)
    const source = typeof from === 'string'      ? await readYAML(from, project) :
                   from instanceof YAML.Document ? from :
                   new YAML.Document(from)

    if (!target?.contents) {
        if (typeof into === 'string' && typeof from === 'string') {
            if (project) await writeYAML(into, source)
            else await copy(from, into)
            return source
        } else if (typeof into === 'string') {
            await writeYAML(into, source)
            return source
        }
        throw new Error(`Target YAML doesn't exist`)
    }

    const { forceOverwrite, additions = [], overwrites = [], deletions = [], relationships = [] } = semantics
    const path = keyPath => keyPath.split('.').filter(k => k)

    // Seq members correspond unless a shared top-level key holds a different scalar.
    // {name:x} enriches {name:x,...}; {name:x,alias:a} and {name:x,alias:b} stay distinct.
    const conflict = (a, b) => Object.keys(a).some(k =>
        k in b && (typeof a[k] !== 'object' || typeof b[k] !== 'object') && JSON.stringify(a[k]) !== JSON.stringify(b[k]))
    const same = (a, b) => {
        if (YAML.isMap(a) && YAML.isMap(b)) { const x = a.toJSON(), y = b.toJSON(); return !conflict(x, y) && !conflict(y, x) }
        return JSON.stringify(a.toJSON?.() ?? a.value) === JSON.stringify(b.toJSON?.() ?? b.value)
    }
    const has = (seq, node) => YAML.isSeq(seq) && seq.items.some(x => same(x, node))

    // `where` matches a node iff every constraint holds on its JSON projection.
    const matches = (node, where) => {
        const json = node.toJSON?.() ?? {}
        const at = (o, k) => path(k).reduce((p, s) => p?.[s], o)
        return Object.entries(where).every(([k, v]) =>
            Array.isArray(v) ? v.every(x => at(json, k) === x) : at(json, k) === v)
    }

    // Resolve a descriptor to a live node:
    //   'a.b.c' -> getIn; {in,where} -> matching seq member; [entry,'rel'] -> getIn on entry.
    const locate = (doc, d) => {
        if (d == null) return undefined
        if (typeof d === 'string') return doc.getIn(path(d))
        if (Array.isArray(d)) {
            const [base, keyPath] = d
            const node = locate(doc, base)
            return keyPath ? node?.getIn(path(keyPath)) : node
        }
        const seq = locate(doc, d.in)
        return YAML.isSeq(seq) ? seq.items.find(n => matches(n, d.where)) : undefined
    }

    // Generic deep-merge: recurse maps, enrich matching seq members, union scalars.
    // Unmatched map members are placed by the passes below. Target scalars win unless forced.
    const mergeNode = (t, s) => {
        if (YAML.isMap(t) && YAML.isMap(s)) {
            for (const pair of s.items) {
                const tv = t.get(pair.key.value, true)
                if (tv === undefined) t.add(pair)
                else mergeNode(tv, pair.value)
            }
        } else if (YAML.isSeq(t) && YAML.isSeq(s)) {
            for (const item of s.items) {
                const match = t.items.find(x => same(x, item))
                if (match) mergeNode(match, item)
                else if (YAML.isScalar(item)) t.add(item)
            }
        } else if (forceOverwrite && YAML.isScalar(t) && YAML.isScalar(s) && t.comment !== 'cds.noOverwrite') {
            t.value = s.value
        }
    }
    mergeNode(target.contents, source.contents)

    // Placement: add matched (and relationship-referenced) template entries not already present.
    const isEntry = e => e && typeof e === 'object' && !Array.isArray(e) && e.in !== undefined
    const insertNode = ins => Array.isArray(ins) ? (ins.length === 1 ? ins[0] : undefined) : ins
    const relEntries = relationships.flatMap(r => [r.into?.[0], ...[].concat(r.insert).map(insertNode)])
    for (const entry of [...additions, ...relEntries].filter(isEntry)) {
        const seq = locate(target, entry.in)
        if (!YAML.isSeq(seq)) continue
        const clone = locate(source, entry)
        if (clone && !has(seq, clone)) {
            entry.at !== undefined ? seq.items.splice(entry.at, 0, clone) : seq.add(clone)
        }
    }

    // Relationships: wire a value into a target seq. [entry,'k'] -> {k: value}; [entry] -> the node.
    for (const { insert, into } of relationships) {
        const [baseEntry, seqPath, prop] = into
        const seq = locate(target, seqPath ? [baseEntry, seqPath] : baseEntry)
        if (!YAML.isSeq(seq)) continue
        for (const ins of Array.isArray(insert) && typeof insert[0] === 'object' ? [insert] : [].concat(insert)) {
            const [srcEntry, valueKey] = Array.isArray(ins) ? ins : [ins]
            const srcNode = locate(target, srcEntry)
            if (!srcNode) continue
            const ref = prop || valueKey
            const node = ref ? target.createNode({ [ref]: (valueKey ? srcNode.get(valueKey) : srcNode.get(ref)) }) : srcNode
            if (!has(seq, node)) seq.add(node)
        }
    }

    // Fill the bare nodes relationships just added from their full source counterparts.
    if (relationships.length) mergeNode(target.contents, source.contents)

    // Overwrites: set a (possibly nested) key on a located node.
    for (const { item, withValue } of overwrites) {
        const [base, keyPath] = Array.isArray(item) ? item : [undefined, item]
        const node = base ? locate(target, base) : target.contents
        const keys = path(typeof base === 'string' ? base : keyPath)
        if (node?.getIn(keys.slice(0, -1)) !== undefined || base && typeof base !== 'string') {
            (node.getIn(keys.slice(0, -1)) ?? node).set(keys.at(-1), withValue)
        }
    }

    // Deletions: remove the matched node (or a sub-key), then cascade-remove references to it.
    for (const { item, key, relationships: refs } of deletions) {
        const seq = locate(target, item.in)
        const node = locate(target, item)
        if (!YAML.isSeq(seq) || !node) continue
        const removed = node.toJSON()
        key ? node.deleteIn(path(key)) : seq.delete(seq.items.indexOf(node))
        for (const { removeProperty, allWithin } of refs ?? []) {
            const [parentPath, childPath, prop] = allWithin
            for (const parent of locate(target, parentPath)?.items ?? []) {
                const list = parent.getIn(path(childPath))
                const i = list?.items?.findIndex(n => n.get?.(prop) === removed[removeProperty]) ?? -1
                if (i > -1) list.delete(i)
            }
        }
    }

    typeof into === 'string' && await writeYAML(into, target)
    return target
}

/**
 * @param {...(string | Object | YAML.Document)} src The source to merge from.
 * @returns {{
 *   into: (dst: (string | Object | YAML.Document), options?: {project?: Object, semantics?: MergingSemantics}) => Promise<any>,
 *   remove: (items: (string | object)[]) => Promise<void>
 * }} An object with an 'into' method to merge the sources into the specified destination.
 */
module.exports.merge = (...src) => {
  return {
    /**
     * Merges sources into the specified destination.
     * @param {(string | Object | YAML.Document)} dst File path or object to merge into.
     * @param {Object} [options] Merging options.
     * @param {Object} [options.project] Project descriptor used for Mustache replacements.
     * @param {MergingSemantics} [options.semantics] Merging algorithm semantics.
     * @returns {Promise} A promise resolving to the merged object.
     */
    into: (dst, { with: withProject, project, ...semantics } = {}) => {
      if (Object.keys(semantics).length === 0) semantics = undefined
      project ??= withProject // to allow { with: project } for a more fluent API
      const isYAML = typeof dst === 'string' && ['.yaml', '.yml', '.yaml.hbs', '.yml.hbs'].some(ext => dst.endsWith(ext))
      const _merge = isYAML ? _mergeYAML : _mergeJSON
      const target = typeof dst === 'string' ? resolve(cds.root, dst) : dst
      if (typeof src[src.length - 1] === 'string') {
        return _merge(target, join(...src), project, semantics)
      } else {
        return _merge(target, ...src, project, semantics)
      }
    },
    /**
     * Removes items from the specified YAML file.
     * @param {(string | object)[]} items An array of dotted‐path strings or objects to remove.
     * @returns {Promise<void>} A promise that resolves once the file is updated.
     */
    remove: async items => {
      const yaml = await readYAML(resolve(cds.root, ...src))
      for (const item of items) {
        if (typeof item === 'string') {
          const keys = item.split('.')
          let node = yaml
          for (let i = 0; i < keys.length - 1; i++) {
            node = node.get(keys[i])
            if (node === undefined) break
          }
          node?.delete?.(keys[keys.length - 1])
        } else if (item && typeof item === 'object') {
          const stack = [{ node: yaml, obj: item }]
          while (stack.length) {
            const { node, obj } = stack.pop()
            for (const [k, v] of Object.entries(obj)) {
              const child = node.get(k)
              if (YAML.isSeq(child)) {
                child.items = child.items.filter(x => {
                  if (YAML.isMap(x)) {
                    return !Object.entries(v).every(([kk, vv]) => x.get(kk) === vv)
                  }
                  return true
                })
              } else if (YAML.isMap(child)) {
                stack.push({ node: child, obj: v })
              }
            }
          }
        }
        await writeYAML(join(...src), yaml)
      }
    }
  }
}


/**
 * A location in a document. One of:
 *  - a dotted key path from the root, e.g. `'modules'` or `'a.b.c'`;
 *  - a {@link MatchedNode}, i.e. the member of a collection satisfying a `where` predicate;
 *  - a based path `[base, keyPath?]` resolving `keyPath` relative to the node `base` denotes
 *    (with `keyPath` omitted, the pair denotes `base` itself).
 * @typedef {string | MatchedNode | [Descriptor, string?]} Descriptor
 */

/**
 * @typedef {Object} MatchedNode
 * @property {Descriptor} in - the collection to search
 * @property {Object.<string, (string | number | boolean | Array)>} where - constraints on the
 *   node's JSON projection; an array value requires each of its entries to be present
 * @property {number} [at] - insertion index for additions (appended when omitted)
 */

/**
 * @typedef {Object} Overwrites
 * @property {Descriptor} item - location of the value to overwrite
 * @property {string | number | boolean} withValue - replacement value
 */

/**
 * @typedef {Object} Deletion
 * @property {MatchedNode} item - matched node to delete
 * @property {string} [key] - dotted key path of a sub-property to delete instead of the whole node
 * @property {Object[]} [relationships] - references to cascade-remove after deletion
 * @property {string} relationships[].removeProperty - property of the removed node to match on
 * @property {string[]} relationships[].allWithin - `[parentPath, childPath, prop]` naming the
 *   sibling collections and the referencing property to strip
 */

/**
 * @typedef {Object} Relationship
 * @property {Descriptor | Descriptor[] | [Descriptor, string]} insert - source node(s), or a
 *   `[entry, key]` pair whose `key` value is wired in
 * @property {[Descriptor, string?, string?]} into - `[baseEntry, seqPath?, prop?]` naming the
 *   target sequence and, optionally, the property key the wired value is written under
 */

/**
 * @typedef {Object} MergingSemantics
 * @property {boolean} [forceOverwrite] - overwrite existing scalar values from the template
 * @property {MatchedNode[]} [additions] - matched nodes to add from the source template
 * @property {Overwrites[]} [overwrites] - values to overwrite at the given locations
 * @property {Deletion[]} [deletions] - matched nodes (or sub-keys) to delete
 * @property {Relationship[]} [relationships] - relationships to wire into target sequences
 */

